file.content:
/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages.
   Phase 5: the ending. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --color-accent-hover: #E2C35C;
  --color-error: #F28B82; /* 6.9:1 on the background */
  /* The same colours as bare numbers, for see-through versions: rgb(var(--rgb-accent) / 0.1). */
  --rgb-background: 31 26 24;
  --rgb-foreground: 250 250 249;
  --rgb-accent: 212 175 55;
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
  color-scheme: dark;
}

/* Light theme (phase 6; the user asked for a switch 2026-09-13), from MASTER.md's light palette. The background is the
   ivory Qur'an photo's own (#F4F5F2 at its edges, warmed a shade), as the dark one is the footage's. The gold is
   deepened from MASTER's #A16207, which is 4.48:1 on this background, to #9A5F07 (4.8:1) so small gold text passes.
   The muted grey is warm stone rather than MASTER's cool slate, so warm and cool greys don't mix
   (taste-skill:redesign-skill). */
:root[data-theme='light'] {
  --color-background: #F5F4F1;
  --color-foreground: #1C1917;
  --color-muted-foreground: #57534E;
  --color-accent: #9A5F07;
  --color-accent-hover: #7C4A05;
  --color-error: #B42318; /* 6:1 on the background */
  --rgb-background: 245 244 241;
  --rgb-foreground: 28 25 23;
  --rgb-accent: 154 95 7;
  color-scheme: light;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
html {
  scrollbar-width: none;
}

html::-webkit-scrollbar {
  display: none;
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen plus the
   timeline in main.js (--timeline, in screens, which main.js also sets): the rest, the opening, then a short
   hold on the open book before the page moves on to the ending. Phones scroll less far (--pace), because a
   finger moves further per swipe than a mouse wheel per click. */
.hero {
  --timeline: 3.05;
  --pace: 1;
  position: relative;
  height: calc(100vh + var(--timeline) * var(--pace) * 100vh);
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

/* Phones and tablets: a swipe stops at each section, and a hard one can't carry past it (the user, 2026-09-14): the
   closed book, the open book, the ending, and the top of the footer, which then scrolls freely. The browser does the
   stopping, so it feels like the phone's own scrolling. On computers main.js glides into place instead. Not under
   reduced motion, or while main.js glides the page itself (.free-scroll). */
@media (hover: none) and (pointer: coarse) {
  html:not(.still, .free-scroll) {
    scroll-snap-type: y mandatory;
  }
}

/* The book's two stops, in .hero: closed, and open where its screen stops being pinned. */
.snap {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
}

.snap.open {
  top: calc(100% - 100vh);
  top: calc(100% - 100svh);
}

.snap,
.close,
.footer {
  scroll-snap-align: start;
  scroll-snap-stop: always;
}

/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
   scrolling, inside .book, which makes room for the ending in the "Under the book" option. The light in the
   air is a canvas over them (and a second one behind the ending), and never catches clicks. */
.book,
.subject,
.air {
  position: absolute;
  inset: 0;
}

.subject canvas,
.air {
  display: block;
  width: 100%;
  height: 100%;
}

.air {
  pointer-events: none;
}

/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades it out as the cover starts to open. */
.wordmark {
  position: absolute;
  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
  left: 0;
  right: 0;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* The top of the page was "very empty" (the user, 2026-09-13). From taste-skill:redesign-skill's audit: no name or
   navigation, nothing telling a visitor the page scrolls, and wide empty sides round the narrow closed book. Touch
   targets and focus rings from ui-ux-pro-max. */

/* A hint that the page scrolls, under the headline while the book is closed: two words and a fine gold line that runs
   down, over and over (MASTER.md's scroll-story pattern asks for a cue). main.js shows it only where the space under
   the book holds it (.roomy); it fades with the headline, and is left out under reduced motion. */
.scroll-hint {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  margin-top: 1.25rem;
  padding-left: 0.24em; /* balances the letter-spacing after the last letter */
  font-size: 0.6875rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-muted-foreground);
}

.roomy .scroll-hint {
  display: flex;
}

.scroll-hint::after {
  content: '';
  width: 1px;
  height: 2rem;
  background: linear-gradient(var(--color-accent), rgb(var(--rgb-accent) / 0));
  transform-origin: top;
  animation: hint 2.6s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}

@keyframes hint {
  0% {
    opacity: 1;
    transform: scaleY(0);
  }

  55% {
    opacity: 1;
    transform: scaleY(1);
  }

  100% {
    opacity: 0;
    transform: scaleY(1);
  }
}

/* Either side of the closed book, on computers: a small gold heading and a few lines, set toward the book. --s is the
   book's scale (main.js); the closed book is 385 footage pixels wide. They fade with the headline, long before the
   opening cover reaches them. */
.beside {
  position: absolute;
  z-index: 1;
  top: 50%;
  display: none;
  width: min(15rem, calc(50% - 192px * var(--s, 1) - 7rem));
  translate: 0 -50%;
}

@media (min-width: 1024px) {
  .beside {
    display: block;
  }
}

.beside.left {
  right: calc(50% + 192px * var(--s, 1) + clamp(2.5rem, 5vw, 5rem));
  text-align: right;
}

.beside.right {
  left: calc(50% + 192px * var(--s, 1) + clamp(2.5rem, 5vw, 5rem));
}

.beside .label,
.footer .label {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.beside.left .label {
  margin-right: -0.24em; /* the letter-spacing after the last letter would hold it off the edge */
}

.beside .label::after,
.footer .label::after {
  content: '';
  display: block;
  width: 1.5rem;
  height: 1px;
  margin: 0.9rem 0 0.75rem;
  background: currentColor;
  opacity: 0.5;
}

.beside.left .label::after {
  margin-right: 0.24em;
  margin-left: auto;
}

.beside ul {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1rem;
  font-weight: 300;
  line-height: 1.85;
  letter-spacing: 0.02em;
  color: rgb(var(--rgb-foreground) / 0.82);
}

/* The top bar: the name on the left, the two ways in on the right (the user's list; About and Contact go at the
   bottom). It sits on the scene over a short fade of the background colour, so dust never runs through the words, with
   no blur: blurring a moving canvas costs every frame on weak devices. main.js slides it away while the visitor scrolls
   down and brings it back on the way up. */
.topbar {
  position: fixed;
  z-index: 2; /* over the book's screen and the ending */
  top: 0;
  right: 0;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 4.5rem;
  padding: 0 clamp(1rem, 3vw, 2.5rem);
  transition: transform 500ms cubic-bezier(0.32, 0.72, 0, 1);
}

.topbar::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(rgb(var(--rgb-background) / 0.85), rgb(var(--rgb-background) / 0));
  pointer-events: none;
}

.topbar.away:not(:focus-within) {
  transform: translateY(-100%); /* a keyboard user's focus brings it back */
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 44px;
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--color-accent);
  text-decoration: none;
}

/* The small star from the ending's ornament, like the gold tooling on the cover. It turns an eighth on hover. */
.brand .mark {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  overflow: visible;
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
  transition: rotate 700ms cubic-bezier(0.16, 1, 0.3, 1);
}

.brand .mark * {
  vector-effect: non-scaling-stroke;
}

.brand .mark circle {
  fill: var(--color-accent);
  stroke: none;
}

.brand:hover .mark {
  rotate: 45deg;
}

.topbar nav {
  display: flex;
  align-items: center;
  gap: clamp(1.25rem, 2.5vw, 2.25rem);
}

.topbar nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 0.875rem;
  letter-spacing: 0.06em;
  color: rgb(var(--rgb-foreground) / 0.78);
  text-decoration: none;
  white-space: nowrap;
  transition:
    color 200ms ease,
    background-color 200ms ease,
    border-color 200ms ease,
    transform 200ms ease;
}

/* A fine gold underline that draws out on hover. */
.topbar nav a::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 10px;
  left: 0;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
}

.topbar nav a:hover {
  color: var(--color-foreground);
}

.topbar nav a:hover::after,
.topbar nav a:focus-visible::after {
  transform: none;
}

/* The lessons link as a small gold outline, quieter than the ending's solid button. */
.topbar .outlined {
  min-height: 40px;
  padding: 0 1.1rem;
  border: 1px solid rgb(var(--rgb-accent) / 0.6);
  border-radius: 4px;
  color: var(--color-accent);
}

.topbar .outlined::after {
  display: none;
}

.topbar .outlined:hover {
  border-color: var(--color-accent);
  background: rgb(var(--rgb-accent) / 0.1);
  color: var(--color-accent);
}

.topbar .outlined:active {
  transform: scale(0.98);
}

/* The light and dark switch, at the end of the bar: a half-filled circle that turns over when the page changes, rather
   than the usual sun and moon (taste-skill:redesign-skill). The tryout also has sun and moon, and words. */
.theme {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  margin-right: -0.625rem; /* the icon lines up with the bar's edge; the rest is touch area */
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.875rem;
  letter-spacing: 0.06em;
  color: rgb(var(--rgb-foreground) / 0.78);
  cursor: pointer;
  transition: color 200ms ease;
}

.theme:hover {
  color: var(--color-foreground);
}

.theme > * {
  display: none;
}

.theme svg {
  width: 1.25rem;
  height: 1.25rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.25;
  stroke-linecap: round;
}

.theme .half {
  display: block;
  transition: rotate 600ms cubic-bezier(0.16, 1, 0.3, 1);
}

.theme .half path {
  fill: currentColor;
  stroke: none;
}

[data-theme='light'] .theme .half {
  rotate: 180deg;
}

.brand:focus-visible,
.topbar nav a:focus-visible,
.theme:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

@media (pointer: coarse) {
  .topbar .outlined {
    min-height: 44px;
  }
}

@media (max-width: 479px) {
  .topbar {
    height: 4rem;
  }

  .topbar nav {
    gap: 1rem;
  }

  .topbar nav a {
    font-size: 0.8125rem;
  }

  .topbar .outlined {
    padding: 0 0.8rem;
  }

  /* Too narrow for the name beside both links: the star stands in for it, and screen readers still get the name. */
  .topbar .brand .name {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

/* The top bar and the words beside the book arrive a beat after the page loads, one after another. */
@media (prefers-reduced-motion: no-preference) {
  .topbar > *,
  .beside > * {
    animation: arrive 1000ms cubic-bezier(0.16, 1, 0.3, 1) backwards;
    animation-delay: calc(250ms + var(--i, 0) * 120ms);
  }

  .topbar > * {
    --from: -0.5rem;
  }

  .topbar nav {
    --i: 1;
  }

  .beside .label {
    --i: 2;
  }

  .beside ul {
    --i: 3;
  }
}

@keyframes arrive {
  from {
    opacity: 0;
    translate: 0 var(--from, 0.5rem);
  }
}

/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
.aayat {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.group {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
}

.page {
  position: absolute;
  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
  width: calc(375px * var(--s, 1));
  height: calc(560px * var(--s, 1));
  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  gap: 1.25em;
  overflow: hidden;
  text-align: center;
  color: #2B211B; /* dark ink, 14:1 on the cream page */
}

.page p {
  margin: 0;
}

.page.right {
  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
  font-size: calc(30px * var(--s, 1));
}

.page.left {
  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
  font-size: calc(16px * var(--s, 1));
}

.arabic {
  font-family: var(--font-arabic);
  line-height: 2.2; /* room for the marks above and below the letters */
}

.marker {
  color: #A16207; /* gold only for the small accents */
}

.surah {
  padding-left: 0.15em;
  font-family: var(--font-display);
  font-size: 1.2em;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #8A6A1F;
}

.meaning {
  display: none;
  font-weight: 400;
  line-height: 1.6;
  color: #3A302A;
}

.ref {
  font-size: 0.85em;
  letter-spacing: 0.08em;
  color: #6B5E55;
}

/* Phase 5: the ending, one line and two ways in, on the screen after the book. The gold dust carries on behind it
   on a second canvas (atmosphere.js). The spacing, 4px corners, no shadow and gentle rise follow
   taste-skill:minimalist-skill; one gold button leads and the other stays quieter (ui-ux-pro-max: primary-action). */
.close {
  position: relative;
  isolation: isolate; /* keeps .inner over the dust without lifting it over the options panels */
  display: grid;
  place-items: center;
  min-height: 100vh;
  min-height: 100svh;
  padding: 6rem 1.5rem;
}

.close .inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.25rem;
  width: 100%;
  max-width: 40rem;
  text-align: center;
}

/* The ending arrives in order: the star and its rules, the line, then the buttons, 120ms apart (ui-ux-pro-max
   motion data, "Scroll Reveal": children a beat apart, a small rise). main.js sets .pending until it scrolls into
   view. Leaving is quicker than arriving. */
.close .inner > * {
  transition:
    opacity 700ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * 120ms);
}

.close .inner > :nth-child(2) {
  --i: 1;
}

.close .inner > :nth-child(3) {
  --i: 2;
}

.close.pending .inner > * {
  opacity: 0;
  transform: translateY(16px);
  transition-duration: 250ms;
  transition-delay: 0s;
}

/* Behind the words, and never over the book: a warm light where the book's light was, and a large gold star in thin
   lines that turns once every four minutes. From taste-skill:minimalist-skill: a section shouldn't be empty and flat
   (soft light, fine geometric lines), and may have one very slow ambient movement. */
.close .backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
}

.close .backdrop::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 50% 45% at 50% 50%, rgb(var(--rgb-accent) / 0.1), rgb(var(--rgb-accent) / 0.04) 50%, rgb(var(--rgb-accent) / 0));
}

.rosette {
  position: absolute;
  top: 50%;
  left: 50%;
  /* On a computer the star nearly fills the screen's height. An upright phone is narrower than it is tall, so there it
     only filled the width and looked small (the user, 2026-09-14): it grows toward the same share of the height, up
     to 125% of the width, so the outer ring runs past the sides while the star inside stays whole. */
  width: min(52rem, max(96vmin, min(125vw, 78vh)));
  width: min(52rem, max(96vmin, min(125vw, 78svh)));
  height: auto;
  translate: -50% -50%;
  overflow: visible;
  fill: none;
  stroke-width: 1;
  opacity: 0.16;
  animation: turn 240s linear infinite;
}

@keyframes turn {
  to {
    rotate: 1turn;
  }
}

/* A small gold star between two fine rules, like the gold tooling on the cover. The rules draw outward and the star
   turns into place as the ending arrives. */
.ornament {
  width: 13rem;
  height: auto;
  margin-bottom: -0.75rem;
  overflow: visible;
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
}

.rosette *,
.ornament * {
  vector-effect: non-scaling-stroke; /* hairlines at any size */
}

.ornament circle {
  fill: var(--color-accent);
  stroke: none;
}

.ornament .rule {
  opacity: 0.6;
  transform-box: fill-box;
  transition: transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) calc(var(--delay, 0ms) + 200ms);
}

.ornament .left {
  transform-origin: right center;
}

.ornament .right {
  transform-origin: left center;
}

.ornament .star {
  transform-box: fill-box;
  transform-origin: center;
  transition:
    opacity 600ms ease var(--delay, 0ms),
    transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) var(--delay, 0ms);
}

.close.pending .ornament .rule {
  transform: scaleX(0);
  transition-duration: 250ms;
  transition-delay: 0s;
}

.close.pending .ornament .star {
  opacity: 0;
  transform: rotate(-90deg) scale(0.5);
  transition-duration: 250ms;
  transition-delay: 0s;
}

/* A quiet name at the very bottom. The headline stands in until the site name is chosen. */
.signoff {
  position: absolute;
  z-index: 1;
  right: 0;
  bottom: 2rem;
  left: 0;
  margin: 0;
  padding-left: 0.3em; /* balances the letter-spacing after the last letter */
  font-family: var(--font-display);
  font-size: 0.75rem;
  letter-spacing: 0.3em;
  text-align: center;
  text-transform: uppercase;
  color: var(--color-accent);
  opacity: 0.8; /* still over 5:1 on the background */
  transition: opacity 700ms ease 600ms;
}

.close.pending .signoff {
  opacity: 0;
  transition-delay: 0s;
}

.close h2 {
  margin: 0;
  max-width: 30ch;
  font-size: clamp(1.375rem, 1.1rem + 1.1vw, 2rem);
  font-weight: 300;
  line-height: 1.35;
  letter-spacing: 0.01em;
  text-wrap: balance;
}

.entry {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem 1rem;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 1.75rem;
  border: 1px solid var(--color-accent);
  border-radius: 4px;
  font-size: 0.9375rem;
  letter-spacing: 0.06em;
  color: var(--color-accent); /* 8:1 on the background */
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 200ms ease,
    border-color 200ms ease,
    color 200ms ease,
    transform 200ms ease;
}

.button.primary {
  background: var(--color-accent);
  color: var(--color-background); /* 8:1 on the gold */
}

.button:hover {
  background: rgb(var(--rgb-accent) / 0.1);
}

.button.primary:hover {
  border-color: var(--color-accent-hover);
  background: var(--color-accent-hover);
}

.button:active {
  transform: scale(0.98);
}

.button:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

@media (max-width: 767px) {
  .close {
    padding: 4rem 1.5rem;
  }

  .signoff {
    bottom: 1.5rem;
  }

  .entry {
    flex-direction: column;
    width: 100%;
    max-width: 20rem;
  }
}

@media (max-width: 767px) {
  .hero {
    --pace: 0.666; /* two thirds as far */
  }

  /* Plain ink on phones. The tryout that puts the surah name under the book, off the page, needs it. */
  .group {
    mix-blend-mode: normal;
  }

  /* The surah name and reference stay on the left page, as on a computer (the user, 2026-09-14). The English meaning is
     too long for a page this small. */
  .page.left {
    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
    font-size: max(9px, calc(16px * var(--s, 1)));
  }

  .page.left .meaning {
    display: none;
  }
}

/* The bottom of the page: who teaches and how to get in touch, then the links (the user's list: Free Qaida, One-to-one
   lessons, About the teacher, Contact). From taste-skill:minimalist-skill: generous space, hairline dividers, no cards
   or shadows, 4px corners, a quiet rise into view, in the page's own gold, Cinzel and Jost rather than the skill's fonts.
   Form rules from ui-ux-pro-max: a visible label on every field, the reason under the field, 48px fields, autofill. */
.footer {
  position: relative;
  isolation: isolate; /* keeps the words over the dust without lifting them over the options panels */
  padding: clamp(5rem, 10vw, 8rem) clamp(1.5rem, 5vw, 4rem) 2rem;
  border-top: 1px solid rgb(var(--rgb-foreground) / 0.1);
  /* At least a screen tall, so at the very bottom the ending never shows above it (the user, 2026-09-14). */
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100svh;
}

.footer > .footer-inner {
  flex: 1 0 auto;
}

/* The small star from the cover's tooling, sitting on the line. */
.footer-mark {
  position: absolute;
  z-index: 1;
  top: 0;
  left: 50%;
  width: 3.25rem;
  height: 1.25rem;
  padding: 0 1rem;
  translate: -50% -50%;
  overflow: visible;
  background: var(--color-background);
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
}

.footer-mark * {
  vector-effect: non-scaling-stroke;
}

.footer-mark circle {
  fill: var(--color-accent);
  stroke: none;
}

.footer-inner {
  display: grid;
  gap: 4.5rem;
  max-width: 64rem;
  margin: 0 auto;
}

@media (min-width: 900px) {
  .footer-inner {
    grid-template-columns: 5fr 6fr;
    gap: clamp(4rem, 8vw, 7rem);
  }
}

/* Over the gold dust, which atmosphere.js draws on a canvas behind the footer. */
.footer-inner,
.footer-base {
  position: relative;
  z-index: 1;
}

.about,
.contact {
  scroll-margin-top: 6rem; /* clear of the top bar when a link jumps here */
}

.footer .lead {
  margin: 0;
  font-size: clamp(1.625rem, 1.3rem + 1.2vw, 2.25rem);
  font-weight: 300;
  line-height: 1.25;
  text-wrap: balance;
}

.years,
.intro {
  margin: 0.75rem 0 0;
  line-height: 1.6;
  color: var(--color-muted-foreground);
}

.bio {
  max-width: 34ch;
  margin: 1.75rem 0 0;
  font-size: 1.0625rem;
  font-weight: 300;
  line-height: 1.7;
  color: rgb(var(--rgb-foreground) / 0.82);
  text-wrap: pretty;
}

.reach {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1rem;
  margin-top: 2rem;
}

.whatsapp {
  gap: 0.625rem;
}

.whatsapp svg {
  width: 1.125rem;
  height: 1.125rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linejoin: round;
}

.show-form {
  display: none; /* TRYOUT "Email form: Here, behind a button" shows it */
  background: none;
  font-family: inherit;
}

/* The way to the contact page, quieter than the WhatsApp button beside it: a link, not a second outlined button
   (taste-skill:redesign-skill, "always one filled button and one ghost button"). TRYOUT "On its own page" shows it. */
.email-page {
  display: none;
  align-items: center;
  min-height: 48px;
  padding: 0 0.25rem;
  font-size: 0.9375rem;
  letter-spacing: 0.06em;
  color: rgb(var(--rgb-foreground) / 0.78);
  text-decoration: underline;
  text-decoration-color: rgb(var(--rgb-accent) / 0.5);
  text-underline-offset: 0.35em;
  transition:
    color 200ms ease,
    text-decoration-color 200ms ease;
}

.email-page:hover {
  color: var(--color-foreground);
  text-decoration-color: var(--color-accent);
}

.email-page:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

/* "or send an email", between two fine rules. */
.or {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin: 2.5rem 0 0;
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  color: var(--color-muted-foreground);
}

.or::before,
.or::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgb(var(--rgb-foreground) / 0.1);
}

.enquiry {
  display: grid;
  gap: 1.25rem;
  margin-top: 1.75rem;
}

.field {
  display: grid;
  gap: 0.5rem;
}

.field label {
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  color: var(--color-muted-foreground);
}

.field input,
.field textarea {
  width: 100%;
  min-height: 48px;
  padding: 0.75rem 0.875rem;
  border: 1px solid rgb(var(--rgb-foreground) / 0.16);
  border-radius: 4px;
  background: var(--color-background); /* solid, so the dust never drifts behind what's being typed */
  font: inherit;
  font-size: 1rem; /* 16px, so phones don't zoom in when a field is tapped */
  font-weight: 300;
  color: var(--color-foreground);
  transition:
    border-color 200ms ease,
    background-color 200ms ease;
}

.field textarea {
  min-height: 7.5rem;
  line-height: 1.6;
  resize: vertical;
}

.field input:hover,
.field textarea:hover {
  border-color: rgb(var(--rgb-foreground) / 0.3);
}

.field input:focus-visible,
.field textarea:focus-visible {
  border-color: var(--color-accent);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.field [aria-invalid='true'] {
  border-color: var(--color-error);
}

.error {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--color-error);
}

.send {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.5rem;
  margin-top: 0.5rem;
}

.enquiry .button {
  font-family: inherit;
}

.button:disabled {
  opacity: 0.6;
  cursor: progress;
}

.privacy {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--color-muted-foreground);
}

.status {
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.6;
}

.status:empty {
  display: none;
}

.status[data-state='failed'] {
  color: var(--color-error);
}

/* The last row: the name, the four links, and the copyright line, above a fine rule. */
.footer-base {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem 2.5rem;
  max-width: 64rem;
  margin: clamp(4.5rem, 9vw, 7rem) auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid rgb(var(--rgb-foreground) / 0.1);
}

.footer-base nav {
  display: flex;
  flex-wrap: wrap;
  column-gap: 1.75rem;
}

.footer-base nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 0.875rem;
  letter-spacing: 0.04em;
  color: rgb(var(--rgb-foreground) / 0.78);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 0.35em;
  transition:
    color 200ms ease,
    text-decoration-color 200ms ease;
}

.footer-base nav a:hover {
  color: var(--color-foreground);
  text-decoration-color: var(--color-accent);
}

.footer-base nav a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

.copyright {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--color-muted-foreground);
}

/* Each part rises gently into view the first time the bottom scrolls in, 80ms apart (footer.js sets .pending; not
   under reduced motion). */
.footer .reveal {
  transition:
    opacity 600ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: calc(var(--i, 0) * 80ms);
}

.contact.reveal {
  --i: 1;
}

.footer-base.reveal {
  --i: 2;
}

.footer.pending .reveal {
  opacity: 0;
  transform: translateY(12px);
}

@media (max-width: 767px) {
  .footer-base {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
.still .hero {
  height: auto;
}

.still .group {
  transition: none;
}

.still .close.pending .inner > *,
.still .close.pending .signoff,
.still .close.pending .ornament .star {
  opacity: 1;
  transform: none;
}

.still .close.pending .ornament .rule {
  transform: none;
}

.still .rosette {
  animation: none;
}

.still .scroll-hint {
  display: none; /* the book is shown open, with nothing to scroll through */
}

.still .topbar {
  transition: none;
}

/* Light mode runs the same hero as dark: its own footage of the ivory Qur'an opening, on the same timeline, with
   the aayat on its pages. The page positions above suit both, which frame the book the same way. */

[data-theme='light'] .signoff {
  opacity: 1; /* the deeper gold needs its full strength for text this small */
}

.rosette stop {
  stop-color: var(--color-accent); /* over the gold written into the SVG, so it follows the theme */
}

/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
   delete everything below. */
[data-arabic='scheherazade'] {
  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
}

[data-left='meaning'] .meaning {
  display: block;
}

/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
[data-ink='flat'] .group {
  mix-blend-mode: normal;
}

.tryout input[type='range'] {
  width: 10em;
  accent-color: #d4af37;
}

.tryout output {
  min-width: 7em;
  font-variant-numeric: tabular-nums;
}

/* Free-text fields (window.addText in main.js), for typing a headline, sentence or label exactly as wanted. */
.tryout input[type='text'] {
  flex: 1;
  min-width: 12em;
  padding: 6px 8px;
  border: 1px solid #5c5048;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.06);
  font: inherit;
  color: #e7e0d8;
}

.tryout input[type='text']:focus-visible {
  outline: 2px solid #d4af37;
  outline-offset: 1px;
}

.tryout {
  position: fixed;
  z-index: 3; /* over the top bar when it's open tall */
  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
  bottom: 12px;
  max-width: calc(100vw - 24px);
  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
  overflow-y: auto;
  padding: 10px 12px;
  border: 1px solid #3F3A37;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.7);
  font: 13px/1 system-ui, sans-serif;
  color: #e7e0d8;
}

.tryout .readout {
  max-width: 34em;
  margin: 10px 0 2px;
  line-height: 1.4;
  color: #A8A29E;
  font-variant-numeric: tabular-nums;
}

.tryout summary {
  padding: 4px 0;
  cursor: pointer;
}

/* Groups of options inside the panel, from tryoutGroup in main.js. */
.tryout details {
  margin-top: 10px;
  padding-top: 4px;
  border-top: 1px solid #3F3A37;
}

.tryout div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.tryout span {
  min-width: 10em;
  color: #A8A29E;
}

.tryout button {
  padding: 10px 14px;
  border: 1px solid #5c5048;
  border-radius: 999px;
  background: transparent;
  color: #e7e0d8;
  font: inherit;
  cursor: pointer;
}

.tryout button[aria-pressed='true'] {
  border-color: #d4af37;
  color: #d4af37;
}

/* TRYOUT, phones only: how far to scroll through the hero, and where the surah name goes ("On the page" is the
   default, above). */
@media (max-width: 767px) {
  [data-phone-scroll='medium'] .hero {
    --pace: 0.512;
  }

  [data-phone-scroll='short'] .hero {
    --pace: 0.366;
  }

  [data-phone-left='under'] .page.left {
    left: 1.5rem;
    right: 1.5rem;
    width: auto;
    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
    padding: 0;
    font-size: 0.875rem;
    color: var(--color-muted-foreground);
  }

  [data-phone-left='under'] .page.left .surah {
    color: var(--color-accent);
  }

  [data-phone-left='under'] .page.left .ref,
  [data-phone-left='under'] .page.left .meaning {
    color: var(--color-muted-foreground);
  }

  [data-phone-left='under'][data-left='meaning'] .page.left .meaning {
    display: block;
  }
}

/* TRYOUT: no swipe stops with "Swipe stops at each section: No" (main.js, touch screens), or with "Under the book",
   where the ending shares the book's screen. */
html[data-swipe='free'],
html[data-ending='under'] {
  scroll-snap-type: none;
}

/* TRYOUT, phase 5: set on <html> by ending-options.js. Once the user picks, move the chosen rules up to the ending's
   styles and delete the rest, with .book's transition and endAt/placeEnding in main.js if "After the book" wins. */

/* "Under the book", computers only. The ending shares the book's last screen: .close is pulled up over it, and when
   scrolling reaches the end (main.js sets .ended) the open book rises and shrinks by what main.js works out for the
   screen, and the ending fades in underneath. Going back is quicker than arriving. */
.book {
  transition: transform 700ms cubic-bezier(0.32, 0.72, 0, 1);
}

@media (min-width: 768px) {
  [data-ending='under']:not(.still) .hero.ended .book {
    transform: translateY(var(--end-y, 0px)) scale(var(--end-scale, 1));
    transition-duration: 1100ms;
  }

  [data-ending='under']:not(.still) .close {
    display: block;
    height: 100vh;
    height: 100svh;
    min-height: 0;
    margin-top: -100vh;
    margin-top: -100svh;
    padding: 0;
    pointer-events: none;
  }

  [data-ending='under']:not(.still) .close .air,
  [data-ending='under']:not(.still) .close .backdrop,
  [data-ending='under']:not(.still) .close .signoff {
    display: none; /* the open book and its own dust are the picture here */
  }

  [data-ending='under']:not(.still) .close .inner {
    --delay: 450ms; /* the words follow the book's move */
    position: absolute;
    top: var(--end-top, 75%);
    left: 0;
    right: 0;
    margin: 0 auto;
    padding: 0 1.5rem;
    visibility: hidden;
    transition: visibility 0s 300ms;
  }

  [data-ending='under']:not(.still) .hero.ended + .close .inner {
    visibility: visible;
    pointer-events: auto;
    transition: none;
  }
}

/* Button looks. "Gold and outline" is the default, above. */
[data-buttons='outline'] .entry .button.primary {
  background: transparent;
  color: var(--color-accent);
}

[data-buttons='outline'] .entry .button.primary:hover {
  border-color: var(--color-accent);
  background: rgb(var(--rgb-accent) / 0.12);
}

[data-buttons='outline'] .entry .button:not(.primary) {
  border-color: rgb(var(--rgb-foreground) / 0.3);
  color: var(--color-foreground);
}

[data-buttons='outline'] .entry .button:not(.primary):hover {
  border-color: rgb(var(--rgb-foreground) / 0.6);
  background: rgb(var(--rgb-foreground) / 0.06);
}

[data-buttons='text'] .entry {
  gap: 0.5rem 2.5rem;
}

[data-buttons='text'] .entry .button,
[data-buttons='text'] .entry .button:hover,
[data-buttons='text'] .entry .button.primary,
[data-buttons='text'] .entry .button.primary:hover {
  position: relative;
  padding: 0 0.25rem;
  border-color: transparent;
  background: transparent;
  color: var(--color-foreground);
}

[data-buttons='text'] .entry .button.primary,
[data-buttons='text'] .entry .button.primary:hover {
  color: var(--color-accent);
}

[data-buttons='text'] .entry .button::after {
  content: '';
  position: absolute;
  left: 0.25rem;
  right: 0.25rem;
  bottom: 11px;
  height: 1px;
  background: currentColor;
  opacity: 0.45;
  transform: scaleX(0.4);
  transition:
    opacity 200ms ease,
    transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
}

[data-buttons='text'] .entry .button:hover::after,
[data-buttons='text'] .entry .button:focus-visible::after {
  opacity: 1;
  transform: none;
}

/* What sits behind the words, and the name at the very end. "Light and star" and "Show" are the defaults, above. */
[data-backdrop='plain'] .close .backdrop {
  display: none;
}

[data-backdrop='light'] .rosette {
  display: none;
}

[data-signoff='hide'] .signoff {
  display: none;
}

/* TRYOUT, top of the page: set on <html> by top-options.js. Once the user picks, keep what's chosen and delete the
   rest. "Lessons as a button", "Bar slides away", the scroll hint, "What and how" and the half-circle switch are the
   defaults, above. */
[data-topbar='off'] .topbar,
[data-hint='hide'] .scroll-hint,
[data-beside='none'] .beside,
[data-toggle='sunmoon'] .theme .half,
[data-toggle='words'] .theme .half {
  display: none;
}

[data-toggle='sunmoon']:not([data-theme='light']) .theme .sun,
[data-toggle='sunmoon'][data-theme='light'] .theme .moon,
[data-toggle='words'] .theme .words {
  display: block;
}

/* TRYOUT, bottom of the page: set on <html> by footer-options.js. "Side by side", "Open" and "Line and star" are the
   defaults, above. */
[data-footer='stacked'] .footer-inner {
  grid-template-columns: 1fr;
  max-width: 36rem;
}

[data-form='closed'] .footer:not(.form-open) .or,
[data-form='closed'] .footer:not(.form-open) .enquiry,
[data-edge='line'] .footer-mark,
[data-edge='none'] .footer-mark {
  display: none;
}

[data-form='closed'] .footer:not(.form-open) .show-form {
  display: inline-flex;
}

[data-edge='none'] .footer {
  border-top: 0;
}

/* "On its own page" (Claude's pick, set by footer-options.js): the form moves to a contact page of its own, and a link
   to it sits beside the WhatsApp button. */
[data-form='page'] .footer .or,
[data-form='page'] .footer .enquiry {
  display: none;
}

[data-form='page'] .email-page {
  display: inline-flex;
}

